  "Il giornaliero lo compila il responsabile": "Raportin ditor e plotëson përgjegjësi",
  "Registra entrata e uscita. Puoi aggiungere foto e segnalazioni dalla scheda del cantiere.": "Regjistro hyrjen dhe daljen. Mund të shtosh foto dhe sinjalizime nga skeda e kantierit.",
